export interface LessonPlanTemplate {
  id: string;
  topic: string;
  gradeBand: "K-2" | "3-5" | "6-8" | "9-12";
  duration: "15-min" | "30-min" | "45-min" | "full-period";
  title: string;
  objectives: string[];
  materials: string[];
  procedure: string[];
  assessment: string;
  extensions: string;
}

export interface ClassroomActivity {
  id: string;
  title: string;
  icon: string;
  color: string;
  description: string;
  gradeBand: string;
  timeNeeded: string;
  steps: { stepNumber: number; instruction: string; teacherNote: string }[];
  debrief: string[];
}

export interface AssessmentQuestion {
  id: string;
  topic: string;
  question: string;
  options: { text: string; isCorrect: boolean; explanation: string }[];
}

export interface CurriculumStandard {
  framework: "Common Core" | "ISTE" | "CSTA";
  standardId: string;
  description: string;
  topics: string[];
}

export interface ClassroomMaterial {
  id: string;
  title: string;
  type: "handout" | "poster" | "activity-sheet" | "discussion-cards" | "checklist";
  icon: string;
  color: string;
  description: string;
  gradeLevel: string;
  sections: { heading: string; content: string }[];
}

